// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.app.NotificationManagerimport com.roshan.persona.brain.skill.SystemOperationimport com.roshan.persona.common.AppErrorimport com.roshan.persona.common.CorrelationIdimport com.roshan.persona.common.Resultimport com.roshan.persona.system.executor.ResourceCategory/** * NOUS — Notification Handler (Module 10 v2 — Step 10.8 + audit defect G fix). * * Posts notifications via [NotificationManager] with channel idempotency * + POST_NOTIFICATIONS permission check (API 33+). * * ## Channel idempotency (per strategy §"Notifications") * * Android 8+ requires every notification to have a channel. Creating a * channel with the same ID twice is a no-op — but we still check * `getNotificationChannel` first via [NotificationService.ensureChannel] * (idempotent) to avoid the call + log spam. * * ## POST_NOTIFICATIONS permission (API 33+) * * Android 13 (Tiramisu) requires `POST_NOTIFICATIONS` runtime permission. * Without it, `notify()` silently fails (no exception). The handler * checks [NotificationService.hasNotificationPermission] before posting * and returns `Result.Failure(Permission.Denied)` if missing. * * ## Reversibility * * **Reversible via cancel** — undo calls `cancelNotification(id)` to * dismiss the previously-posted notification. * * Implements [ReversibleHandler] with [NotificationPreState] capturing the * notification ID (so undo knows which notification to cancel). * * ## Executor integration (audit defect G fix) * * Now handles [SystemOperation.PostNotification] directly via [execute] — * the Brain can route PostNotification operations through the standard * [com.roshan.persona.system.executor.SystemOperationExecutorImpl] pipeline * (with thermal gating, permission checks, exception mapping) instead of * the special-cased [post] direct-call method. * * ## Resource category * * Notifications use [ResourceCategory.NOTIFICATION] — no shared hardware. * * @see <a href="docs/strategy/module-10-system-strategy-v2.md">§Scope — Notifications</a> */class NotificationHandler(    private val notificationService: NotificationService,) : ReversibleHandler<SystemOperation> {    override val id: String = "notification"    override val displayName: String = "Notification Poster"    override val requiredPermissions: Set<String> = if (        android.os.Build.VERSION.SDK_INT >= android.os.Build.VERSION_CODES.TIRAMISU    ) {        setOf(android.Manifest.permission.POST_NOTIFICATIONS)    } else {        emptySet()    }    override val resourceCategory: ResourceCategory = ResourceCategory.NOTIFICATION    override fun isAvailable(): Boolean = true  // all devices have NotificationManager    override suspend fun execute(operation: SystemOperation): Result<Unit> {        // Route PostNotification through the executor pipeline.        if (operation is SystemOperation.PostNotification) {            return executePostNotification(operation)        }        // Other operation types are unsupported via the executor — callers        // should use the direct [post] method for ad-hoc notifications.        return Result.Failure(            error = AppError.Hardware.Unsupported(                resource = "notification:${operation::class.simpleName}",                cause = null,            ),            correlationId = CorrelationId.generate(),            durationNanos = 0,        )    }    /**     * Execute a [SystemOperation.PostNotification] — posts the notification     * via [AndroidNotificationService] with channel idempotency + permission     * check.     */    private suspend fun executePostNotification(op: SystemOperation.PostNotification): Result<Unit> {        // 1. Check POST_NOTIFICATIONS permission (API 33+).        if (!notificationService.hasNotificationPermission()) {            return Result.Failure(                error = AppError.Permission.Denied(                    android.Manifest.permission.POST_NOTIFICATIONS,                ),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }        // 2. Ensure channel exists (idempotent).        try {            notificationService.ensureChannel(                channelId = op.channelId,                name = op.channelName,                description = "NOUS notifications",                importance = NotificationManager.IMPORTANCE_DEFAULT,            )        } catch (t: Throwable) {            Timber.tag("NotificationHandler").w(t, "ensureChannel failed")        }        // 3. Post.        val success = try {            notificationService.postNotification(                id = op.id,                channelId = op.channelId,                title = op.title,                text = op.text,            )        } catch (t: Throwable) {            Timber.tag("NotificationHandler").w(t, "postNotification failed")            false        }        return if (success) {            Result.Success(Unit, CorrelationId.generate(), 0)        } else {            Result.Failure(                error = AppError.Hardware.Unknown("notification"),                correlationId = CorrelationId.generate(),                durationNanos = 0,            )        }    }    /**     * Post a notification directly (used by SystemFacade for proactive messages).     *     * This is the legacy entry point used by [com.roshan.persona.system.di.SystemFacade.postNotification]     * — the Brain's [SystemOperation.PostNotification] variant now routes     * through [execute] instead.     *     * @param id notification ID (use for cancel).     * @param channelId channel ID (auto-created if missing).     * @param channelName user-visible channel name (e.g., "NOUS Proactive").     * @param title notification title.     * @param text notification body.     * @return [Result.Success] or [Result.Failure].     */    suspend fun post(        id: Int,        channelId: String,        channelName: String,        title: String,        text: String,    ): Result<Unit> = executePostNotification(        SystemOperation.PostNotification(            id = id,            channelId = channelId,            channelName = channelName,            title = title,            text = text,        ),    )    /** Cancel a previously-posted notification by ID. */    suspend fun cancel(id: Int) {        notificationService.cancelNotification(id)    }    /** Cancel all NOUS notifications. */    suspend fun cancelAll() {        notificationService.cancelAll()    }    // ─── ReversibleHandler (for undo support via PersistentUndoStack) ──────    /**     * Pre-state capture — records the notification ID so undo can cancel it.     *     * Returns null if the operation isn't a PostNotification (no undo for     * other operation types).     */    override suspend fun capturePreState(operation: SystemOperation): Any? {        return when (operation) {            is SystemOperation.PostNotification -> NotificationPreState(notificationId = operation.id)            else -> null        }    }    /**     * Restore pre-state — cancels the previously-posted notification by ID.     *     * For PostNotification, "undo" = dismiss the notification. There's no     * "previous notification state" to restore (the notification didn't     * exist before NOUS posted it).     */    override suspend fun restorePreState(operation: SystemOperation, preState: Any?) {        if (preState !is NotificationPreState) return        try {            notificationService.cancelNotification(preState.notificationId)        } catch (t: Throwable) {            Timber.tag("NotificationHandler").w(t, "restorePreState: cancel failed")        }    }    override suspend fun getCurrentState(): Any? = null    override suspend fun isAlreadyInTargetState(operation: SystemOperation): Boolean = false    override fun describeOperation(operation: SystemOperation): String = when (operation) {        is SystemOperation.PostNotification -> "Notification posted: ${operation.title}"        else -> "Notification posted"    }    // ─── Pre-state serialization (audit defect B fix) ─────────────────────    override fun serializePreState(preState: Any?): String? {        if (preState == null) return null        if (preState !is NotificationPreState) {            return com.roshan.persona.system.undo.SystemOperationSerializer.serializePreState(preState)        }        return "{\"type\":\"NotificationPreState\",\"notificationId\":${preState.notificationId}}"    }    override fun deserializePreState(json: String?): Any? {        if (json == null) return null        val map = try {            com.roshan.persona.system.undo.SystemOperationSerializer.parseJsonObject(json)        } catch (t: Throwable) {            return com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }        return when (map["type"] as? String) {            "NotificationPreState" -> NotificationPreState(                notificationId = (map["notificationId"] as? Number)?.toInt() ?: 0,            )            else -> com.roshan.persona.system.undo.SystemOperationSerializer.deserializePreState(json)        }    }    /** Captured pre-state for a posted notification (just the ID — for cancel-on-undo). */    data class NotificationPreState(val notificationId: Int)}
